const feeds = [
  { sourceId: 'whitehouse_presidential_actions', layer: 'official_primary', weight: 100, feedUrl: 'https://www.whitehouse.gov/presidential-actions/feed/' },
  { sourceId: 'whitehouse_briefing_room', layer: 'official_primary', weight: 95, feedUrl: 'https://www.whitehouse.gov/briefing-room/feed/' },
  { sourceId: 'fed_all_feeds', layer: 'macro_market_official', weight: 88, feedUrl: 'https://www.federalreserve.gov/feeds/press_all.xml' },
  { sourceId: 'google_trump_tariff_china', layer: 'news_validation', weight: 60, feedUrl: 'https://news.google.com/rss/search?q=Trump+tariff+China&hl=en-US&gl=US&ceid=US:en' }
];
return feeds.map(feed => ({ json: feed }));

return items.map(item => {
  const j = item.json;
  const title = j.title || '';
  const summary = j.contentSnippet || j.content || j.description || '';
  const text = `${title} ${summary}`.toLowerCase();
  const critical = ['tariff', 'tariffs', 'duties', 'section 301', 'section 232', 'executive order', 'proclamation', 'retaliation', 'trade war'];
  const countries = ['china', 'mexico', 'canada', 'european union', 'eu', 'japan', 'south korea', 'taiwan', 'brazil', 'india'];
  const channels = ['semiconductor', 'chips', 'autos', 'steel', 'aluminum', 'copper', 'oil', 'rare earths', 'supply chain', 'exports', 'imports'];
  const soft = ['considering', 'may', 'could', 'proposal', 'discussion', 'rumor', 'sources say', 'draft'];
  const count = arr => arr.filter(term => text.includes(term)).length;
  let score = 30;
  score += Math.min(count(critical), 2) * 28;
  score += Math.min(count(countries), 2) * 16;
  score += Math.min(count(channels), 2) * 12;
  score -= Math.min(count(soft), 2) * 8;
  score = Math.max(0, Math.min(100, score));
  let alertLevel = 'GREEN';
  if (score >= 78) alertLevel = 'RED';
  else if (score >= 60) alertLevel = 'ORANGE';
  else if (score >= 40) alertLevel = 'YELLOW';
  return { json: { ...j, normalizedTitle: title.trim(), summary: summary.trim(), preScore: score, preAlertLevel: alertLevel } };
});
